{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C26"],
      "claim": "Norethisterone, which shares the 17α-ethynyl-17β-hydroxy-3-keto-4-ene 19-norsteroid core with the query, has an absolute oral bioavailability of 64 ± 8% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Levonorgestrel, a close 13-ethyl analogue of the same 17α-ethynyl-3-keto-4-ene scaffold, has an absolute oral bioavailability of 87 ± 9%, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Etonogestrel, another 17α-ethynyl-3-keto-4-ene progestin, has a mean absolute oral bioavailability of 76.1 ± 22.5%, supporting high F for this steroid family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "17-Methyltestosterone, a 3-keto-4-ene androgenic steroid with a 17α-alkyl group, has good oral bioavailability in humans, supporting the oral absorbability of this steroid class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Abiraterone acetate has very low oral bioavailability (<10%), but this reflects a 3β-acetate prodrug with poor solubility and a different steroid substitution pattern, making it less transferable to the query's 3-keto-4-ene progestin-like core.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C53"],
      "claim": "Anecortave desacetate has low oral bioavailability, but it is a corticosteroid-like soft drug with 17,21-diol and 9,11-ene features that are not representative of the query's 17α-ethynyl progestin scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F >= 20%) based on strong, transferable experimental evidence from 17α-ethynyl-3-keto-4-ene 19-norsteroids such as norethisterone, levonorgestrel, and etonogestrel, whose absolute oral bioavailability values are 62-100%. The query's 16β-dimethylaminophenyl substituent increases lipophilicity and may reduce solubility, but the core steroid pharmacophore is associated with high oral bioavailability. The low-F evidence from abiraterone acetate and anecortave desacetate is less transferable because of different prodrug, soft-steroid, and substitution features.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data exist for the query molecule.",
    "The effect of the 16β-(4-dimethylaminophenyl) substituent on solubility, permeability, and first-pass metabolism is unknown.",
    "High lipophilicity (logP ~5.4) may cause solubility-limited absorption, but the F >= 20% threshold may still be met.",
    "Human absolute bioavailability data are extrapolated from close progestin analogues rather than measured for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

